    AutoConfig.register('transformer', TransformerConfig)
    AutoModelForCausalLM.register(TransformerConfig, TransformerForCausalLM)
except (ImportError, ValueError):
    pass

# Monkey-patch to fix weight tying: directly assign embedding weights to lm_head
_original_from_pretrained = AutoModelForCausalLM.from_pretrained.__func__

@classmethod
def _patched_from_pretrained(cls, *args, **kwargs):
    model = _original_from_pretrained(cls, *args, **kwargs)
    # Find embedding layer
    embed = None
    if hasattr(model, 'model'):
        if hasattr(model.model, 'embed_tokens'):
            embed = model.model.embed_tokens
        elif hasattr(model.model, 'embeddings'):
            embed = model.model.embeddings
    if embed is not None and hasattr(model, 'lm_head'):
        if model.lm_head.weight.data_ptr() != embed.weight.data_ptr():
            model.lm_head.weight = embed.weight
            print(f"Weight tying FIXED: lm_head.weight = embeddings.weight (ptr={embed.weight.data_ptr()})")
        else:
            print("Weight tying already OK")
    else:
        print("WARNING: Could not find embedding layer for weight tying")
    return model

AutoModelForCausalLM.from_pretrained = _patched_from_pretrained

from lm_eval.__main__ import cli_evaluate
cli_evaluate()
